const body = $input.first().json.body || $input.first().json;
const vendors = body.vendors || (body.website ? [{ vendor_name: body.vendor_name || '', website: body.website }] : []);
if (!vendors.length) return [{ json: { _no_vendors: true } }];
const rapidapi_key = (body.rapidapi_key || '').trim();
if (!rapidapi_key) throw new Error('rapidapi_key required in request body');
const supabase_url = (body.supabase_url || process.env.SUPABASE_URL || '').trim();
const supabase_key = (body.supabase_key || process.env.SUPABASE_KEY || '').trim();
return vendors.map(v => ({
  json: {
    vendor_name: v.vendor_name || v.name || '',
    website: (v.website || '').replace(/\/$/, ''),
    g2_slug: v.g2_slug || '',
    rapidapi_key,
    supabase_url,
    supabase_key,
  }
}));

const item = $input.first().json;
// Use provided slug, or derive from vendor name
let slug = item.g2_slug;
if (!slug) {
  // Strip common company suffixes
  const clean = item.vendor_name
    .replace(/\s+(Software|Inc\.?|LLC|Ltd\.?|Corp\.?|Group|Technologies|Tech|Solutions|Platform|Systems)$/i, '')
    .trim();
  slug = clean.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}
return [{ json: { ...item, g2_slug: slug } }];

const vendor = $('Build Slug').item.json;
const resp = $input.first().json;

if (!resp.product_name) {
  return [{ json: { vendor_name: vendor.vendor_name, website: vendor.website, g2_slug: vendor.g2_slug, _has_data: false, _miss_reason: resp.message || 'no_match' } }];
}

// Plausibility check: G2 name should share a word with vendor name
const stopwords = new Set(['software','inc','llc','ltd','corp','platform','solutions','technologies','group','customer','success','the','and','for']);
const vendorWords = new Set(vendor.vendor_name.toLowerCase().split(/\W+/).filter(w => w.length > 2 && !stopwords.has(w)));
const g2Words = new Set(resp.product_name.toLowerCase().split(/\W+/).filter(w => w.length > 2));
const overlap = [...vendorWords].some(w => g2Words.has(w));
if (!overlap) {
  return [{ json: { vendor_name: vendor.vendor_name, website: vendor.website, g2_slug: vendor.g2_slug, _has_data: false, _miss_reason: `plausibility_fail:${resp.product_name}` } }];
}

const cats = Array.isArray(resp.categories) ? resp.categories : (resp.category ? [resp.category] : []);
const g2_categories = cats.map(c => c.name || c).filter(Boolean).slice(0, 8);
const founded = resp.company_founded_year ? String(resp.company_founded_year) : null;
const hq_address = resp.company_location || null;
const plans = Array.isArray(resp.pricing_plans) ? resp.pricing_plans : [];
const pricing = plans.map(p => [p.plan_name, p.plan_price].filter(Boolean).join(': ')).filter(Boolean);
const free_trial = plans.some(p => /free/i.test((p.plan_name || '') + (p.plan_price || '')));
const featText = JSON.stringify(resp.features || '');
const soc2 = /SOC\s*2/i.test(featText);
const gdpr = /\bGDPR\b/i.test(featText);
const compliance = [soc2 && 'SOC 2', gdpr && 'GDPR'].filter(Boolean);

return [{ json: {
  vendor_name: vendor.vendor_name,
  website: vendor.website,
  g2_slug: vendor.g2_slug,
  supabase_url: vendor.supabase_url,
  supabase_key: vendor.supabase_key,
  g2_product_name: resp.product_name,
  g2_url: resp.g2_link || resp.g2_reviews_link || '',
  g2_rating: resp.rating || null,
  g2_review_count: resp.reviews || null,
  g2_market_segment: '',
  g2_categories,
  soc2,
  compliance,
  founded,
  hq_address,
  pricing: pricing.length ? pricing : null,
  free_trial: plans.length ? free_trial : null,
  pricing_source: pricing.length ? 'g2' : null,
  _has_data: !!(resp.rating || resp.reviews || g2_categories.length),
} }];

const item = $input.first().json;

// Build upsert row — only include non-null bonus fields
const row = {
  website: item.website,
  g2_url: item.g2_url,
  g2_rating: item.g2_rating,
  g2_review_count: item.g2_review_count,
  g2_market_segment: item.g2_market_segment || '',
  g2_categories: item.g2_categories,
  soc2: item.soc2,
  compliance: item.compliance,
};
if (item.founded) row.founded = item.founded;
if (item.hq_address) row.hq_address = item.hq_address;
if (item.pricing) { row.pricing = item.pricing; row.pricing_source = item.pricing_source; }
if (item.free_trial !== null) row.free_trial = item.free_trial;

return [{ json: { ...item, _upsert_row: row } }];
